@pytest.mark.parametrize("auth_scenario", ["valid", "invalid", "missing"])
def test_user_login_auth(api_client, host, auth_scenario):
    """
    Test the /user/login endpoint with different authentication scenarios.
    """
    endpoint = '/user/login'
    params = {
        "username": "anyUser",
        "password": "anyPass"
    }
    headers = {}

    if auth_scenario == "valid":
        headers['Authorization'] = f"Bearer {api_client.api_key}"
    elif auth_scenario == "invalid":
        headers['Authorization'] = "Bearer invalid_token"
    elif auth_scenario == "missing":
        headers.pop('Authorization', None)

    # Make API request
    response = api_client.get(endpoint, params=params, headers=headers)

    # Assert response status code for auth scenarios
    if auth_scenario == "valid":
        assert response.status_code == 200, f"Unexpected status code for valid auth: {response.status_code}"
    else:
        assert response.status_code != 200, f"Unexpected success for {auth_scenario} auth"

    # Validate response schema
    response_validation = swagger_validator.validate_schema_by_response(endpoint, 'get', str(response.status_code), response)
    assert response_validation['valid'], f"Response validation failed: {response_validation['message']}"
